Summary:
[{
    "SDK_name": "AppLovin MAX API",
    "API_name": "setIsAgeRestrictedUser",
    "conditions": ["The application should know if the user is in an age-restricted category i.e., under the age of 16, or as defined by the applicable laws. This API should be used to set the flag accordingly."],
    "effects": ["If the user is below the age limit, the API will prevent the collection of user's personal information and the delivery of advertisements to the user.", "It ensures compliance with GDPR, COPPA and other age-related restrictions as well as Apple App Store and Google Play Store policies."],
    "parameter_configuations": [
      {
	      "parameter_values":["true"],
	      "conditions":["If the user is in an age-restricted category."],
	      "effects":["Age restriction flag is set to true indicating that the user is within an age-restricted category."]
      },
      {
	      "parameter_values":["false"],
	      "conditions":["If the user is not in an age-restricted category."],
	      "effects":["Age restriction flag is set to false indicating that the user is not within an age-restricted category."]  
      }
    ]
  }]
